        let threeLoadingPromise = null;
        function ensureThreeJs() {
            if (window.THREE && typeof window.THREE.WebGLRenderer === "function") return Promise.resolve();
            if (threeLoadingPromise) return threeLoadingPromise;
            threeLoadingPromise = new Promise((resolve) => {
                const s = document.createElement("script");
                s.src = "https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js";
                s.async = true;
                s.onload = () => resolve();
                s.onerror = () => resolve();
                document.head.appendChild(s);
            });
            return threeLoadingPromise;
        }
// --- Application State ---
        let isTesting = false;
        let animationId = null;
        let lastTime = performance.now();
        let frameCount = 0;
        let fpsHistory = [];
        const MAX_HISTORY = 120; // Rolling window of data points for graph
        // Throttling Detection State
        let peakBaselineFps = 0;
        let rollingAverageFps = 0;
        let stabilizationCounter = 0;
        const STABILIZATION_FRAMES = 60; // Wait 60 ticks before setting baseline
        // Three.js context
        let scene, camera, renderer, material, quad;
        // DOM Elements
        const btnToggle = document.getElementById('toggle-btn');
        const btnText = document.getElementById('btn-text');
        const btnIcon = document.getElementById('btn-icon');
        const intensitySlider = document.getElementById('intensity-slider');
        const valFps = document.getElementById('val-fps');
        const valPeak = document.getElementById('val-peak');
        const valDrop = document.getElementById('val-drop');
        const statusBadge = document.getElementById('status-badge');
        const fpsCanvas = document.getElementById('fps-canvas');
        const fpsCtx = fpsCanvas.getContext('2d');
        // --- Core Engine: ThreeJS GPU Shader ---
        function initWebGL() {
            const container = document.getElementById('gl-container');
            if (renderer) return; // already init
            scene = new THREE.Scene();
            camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
            renderer = new THREE.WebGLRenderer({ antialias: false, alpha: false });
            renderer.setSize(container.clientWidth, container.clientHeight);
            renderer.setPixelRatio(window.devicePixelRatio); // Full resolution stress
            container.appendChild(renderer.domElement);
            // The Stress Shader: A heavily iterated fractal calculation
            // This guarantees pure ALU (math) bottlenecking on the GPU cores.
            const fragmentShader = `
                uniform float u_time;
                uniform float u_intensity;
                varying vec2 vUv;
                void main() {
                    vec2 p = vUv * 2.0 - 1.0;
                    float maxIters = 50.0 + (u_intensity * 10.0); // Scales iterations
                    float iters = 0.0;
                    vec2 z = p;
                    // Dynamic panning seed based on time to prevent driver caching optimizations
                    vec2 c = vec2(sin(u_time * 0.1), cos(u_time * 0.13)) * 0.5;
                    for(float i=0.0; i<1500.0; i++) {
                        if(i > maxIters) break;
                        z = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y) + c;
                        if(dot(z,z) > 4.0) break;
                        iters++;
                    }
                    float heat = iters / maxIters;
                    // Coloring: Dark blue -> Red -> Yellow (Thermal look)
                    vec3 col = mix(vec3(0.05, 0.05, 0.1), vec3(1.0, 0.2, 0.0), heat);
                    col = mix(col, vec3(1.0, 0.8, 0.2), smoothstep(0.8, 1.0, heat));
                    gl_FragColor = vec4(col, 1.0);
                }
            `;
            const vertexShader = `
                varying vec2 vUv;
                void main() {
                    vUv = uv;
                    gl_Position = vec4(position, 1.0);
                }
            `;
            material = new THREE.ShaderMaterial({
                uniforms: {
                    u_time: { value: 0.0 },
                    u_intensity: { value: parseFloat(intensitySlider.value) }
                },
                vertexShader: vertexShader,
                fragmentShader: fragmentShader,
                depthWrite: false,
                depthTest: false
            });
            quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material);
            scene.add(quad);
            // Handle resize
            const resizeObserver = new ResizeObserver(() => {
                renderer.setSize(container.clientWidth, container.clientHeight);
            });
            resizeObserver.observe(container);
        }
        // --- Render & Telemetry Loop ---
        function runTest() {
            if (!isTesting) return;
            animationId = requestAnimationFrame(runTest);
            const now = performance.now();
            const delta = now - lastTime;
            lastTime = now;
            const currentFps = 1000 / delta;
            // Only update readout every ~200ms to keep UI readable, but graph uses all data
            frameCount++;
            if (frameCount % 10 === 0) {
                const smoothedFps = Math.round(currentFps);
                valFps.innerText = smoothedFps;
                updateTelemetry(smoothedFps);
            }
            // Update Shader
            material.uniforms.u_time.value = now * 0.001;
            material.uniforms.u_intensity.value = parseFloat(intensitySlider.value);
            // Render heavy frame
            renderer.render(scene, camera);
        }
        function updateTelemetry(fps) {
            // Cap crazy startup numbers
            if (fps > 240) fps = 240;
            fpsHistory.push(fps);
            if (fpsHistory.length > MAX_HISTORY) fpsHistory.shift();
            drawGraph();
            // Algorithm for Throttling Detection
            if (stabilizationCounter < STABILIZATION_FRAMES) {
                stabilizationCounter++;
                if (fps > peakBaselineFps) {
                    peakBaselineFps = fps;
                    valPeak.innerText = peakBaselineFps;
                }
                statusBadge.innerText = "Calibrating...";
                statusBadge.className = "status-pill status-idle";
            } else {
                // Calculate rolling average of last 10 ticks
                const slice = fpsHistory.slice(-10);
                rollingAverageFps = slice.reduce((a, b) => a + b, 0) / slice.length;
                if (peakBaselineFps > 0) {
                    const variance = ((peakBaselineFps - rollingAverageFps) / peakBaselineFps) * 100;
                    if (variance < 0) {
                        // User might have lowered intensity or background task ended
                        valDrop.innerText = "0%";
                        statusBadge.innerText = "Stable";
                        statusBadge.className = "status-pill status-stable";
                    } else {
                        valDrop.innerText = `-${Math.round(variance)}%`;
                        if (variance >= 15) {
                            statusBadge.innerText = "Throttling";
                            statusBadge.className = "status-pill status-throttling";
                            valDrop.classList.replace('text-orange-400', 'text-red-500');
                        } else {
                            statusBadge.innerText = "Stable";
                            statusBadge.className = "status-pill status-stable";
                            valDrop.classList.replace('text-red-500', 'text-orange-400');
                        }
                    }
                }
            }
        }
        // --- Drawing the Graph ---
        function initGraph() {
            fpsCanvas.width = fpsCanvas.clientWidth;
            fpsCanvas.height = fpsCanvas.clientHeight;
            drawGraph();
        }
        function drawGraph() {
            fpsCtx.clearRect(0, 0, fpsCanvas.width, fpsCanvas.height);
            if (fpsHistory.length === 0) return;
            // Grid lines
            fpsCtx.strokeStyle = '#1e293b';
            fpsCtx.lineWidth = 1;
            fpsCtx.beginPath();
            fpsCtx.moveTo(0, fpsCanvas.height / 2);
            fpsCtx.lineTo(fpsCanvas.width, fpsCanvas.height / 2);
            fpsCtx.stroke();
            // Plot
            fpsCtx.beginPath();
            fpsCtx.lineWidth = 3;
            fpsCtx.lineJoin = "round";
            // Determine max scale dynamically based on peak
            const maxScale = Math.max(120, peakBaselineFps + 10);
            const sliceWidth = fpsCanvas.width / (MAX_HISTORY - 1);
            let x = 0;
            for (let i = 0; i < fpsHistory.length; i++) {
                const fps = fpsHistory[i];
                // normalize height
                const y = fpsCanvas.height - ((fps / maxScale) * fpsCanvas.height);
                if (i === 0) fpsCtx.moveTo(x, y);
                else fpsCtx.lineTo(x, y);
                x += sliceWidth;
            }
            // Gradient Stroke
            const gradient = fpsCtx.createLinearGradient(0, 0, 0, fpsCanvas.height);
            gradient.addColorStop(0, '#34d399'); // Emerald (High FPS)
            gradient.addColorStop(0.5, '#fbbf24'); // Amber
            gradient.addColorStop(1, '#ef4444'); // Red (Low FPS)
            fpsCtx.strokeStyle = gradient;
            fpsCtx.stroke();
            // Fill under graph
            fpsCtx.lineTo(x, fpsCanvas.height);
            fpsCtx.lineTo(0, fpsCanvas.height);
            fpsCtx.fillStyle = 'rgba(239, 68, 68, 0.05)';
            fpsCtx.fill();
        }
        // --- Prewarm Three.js on button hover/focus ---
        const startBtn = document.getElementById('toggle-btn');
        if (startBtn) {
            startBtn.addEventListener('pointerenter', ensureThreeJs, { once: true, passive: true });
            startBtn.addEventListener('focus', ensureThreeJs, { once: true, passive: true });
        }
        // --- UI Interactions ---
        async function toggleTest() {
            await ensureThreeJs();
            if (!window.THREE) return;
            isTesting = !isTesting;
            if (isTesting) {
                initWebGL();
                lastTime = performance.now();
                fpsHistory = []; // clear old data
                peakBaselineFps = 0;
                stabilizationCounter = 0;
                valPeak.innerText = "0";
                valDrop.innerText = "0%";
                intensitySlider.disabled = false;
                btnText.innerText = "Halt Test";
                btnIcon.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z"></path>';
                btnToggle.classList.replace('bg-red-600', 'bg-slate-700');
                btnToggle.classList.replace('hover:bg-red-700', 'hover:bg-slate-800');
                btnToggle.classList.replace('border-red-800', 'border-slate-900');
                runTest();
            } else {
                cancelAnimationFrame(animationId);
                intensitySlider.disabled = true;
                btnText.innerText = "Start Stress Test";
                btnIcon.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>';
                btnToggle.classList.replace('bg-slate-700', 'bg-red-600');
                btnToggle.classList.replace('hover:bg-slate-800', 'hover:bg-red-700');
                btnToggle.classList.replace('border-slate-900', 'border-red-800');
                statusBadge.innerText = "System Idle";
                statusBadge.className = "status-pill status-idle";
            }
        }
        function updateIntensity(val) {
            document.getElementById('intensity-readout').innerText = val + 'x';
            // When user changes intensity, we must reset the peak baseline because the workload changed.
            if (isTesting) {
                peakBaselineFps = 0;
                stabilizationCounter = 0;
                valPeak.innerText = "0";
                statusBadge.innerText = "Recalibrating...";
                statusBadge.className = "status-pill status-idle";
            }
        }
        // --- Init ---
        window.addEventListener('resize', initGraph);
        window.addEventListener('load', initGraph);
